(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const wx2 = Math.sin(sx*0.015+t*0.4)*6 + Math.cos(sy*0.02-t*0.3)*5;
  const wy2 = Math.cos(sy*0.015-t*0.35)*6 + Math.sin(sx*0.018+t*0.45)*5;
  const dx = sx+wx2, dy = sy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 0.88],
    [400+Math.cos(t*0.55+1)*60, 220+Math.sin(t*0.75+4)*40, 0.085, 1.8, 1.02]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((dx-sX)**2+(dy-sY)**2);
    const pulse = 1+Math.sin(t*0.8+sp)*0.15;
    aS += Math.sin(d*f*pulse - t*sp)*w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*w;
    cS += Math.cos(d*f*1.3 - t*sp*0.8 + 2.0)*w*0.5;
  }
  const act=aS/8, inh=iS/8, cor=cS/8;
  const bg = (Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2
    + Math.sin((dx+dy)*0.12+t*2.5)*0.2 + Math.sin((dx-dy)*0.1-t*2)*0.2
    + Math.sin(dx*0.08*dy*0.06+t*0.6)*0.15;
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2), ang=Math.atan2(dy-cy,dx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.03-ang*5+t*0.9))*0.27;
  const lap = Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5+Math.sin((dx*1.5-dy*0.7)*0.05+t*0.7)*0.3;
  const cell = Math.tanh(lap*1.5)*0.3;
  const rd1 = Math.tanh((act - inh*0.7 + cor*0.3)*2.0);
  const rd2 = Math.tanh((act*0.6 - inh + bg*0.2)*1.8);
  const reaction = Math.tanh((rd1*0.6 + rd2*0.4 + bg*0.15 + spiral + cell)*2.0);
  const micro = Math.sin(dx*0.3+t*3)*Math.sin(dy*0.3-t*2.5)*0.08*reaction;
  const blend = reaction*0.7 + cell*0.2 + micro, v = blend*0.5+0.5;
  const pal = [[5,10,45],[12,40,85],[18,90,120],[25,140,130],[160,175,60],[210,160,55],[200,100,60],[150,45,70],[90,20,65],[30,12,55],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:Math.abs(reaction)>0.85?1.2:1.0;
  const glow=Math.max(0, 1-dist/250)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
